var i=`0060-bryndzove-halusky`;var n=`world-0060`;var a=`SK`;var o=`eastern-europe`;var s=4;var r=37;var l={en:`Bryndzové Halušky`,ua:`Бриндзові галушки`};var g={en:`A classic dish from Slovakia, featuring potato, chicken egg, bacon, bryndza. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Словаччина. Основні складники: картопля, куряче яйце, бекон, бринза. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var u=[{en:`Peel and coarsely grate the listed vegetables; squeeze out excess moisture so the mixture will hold together.`,ua:`Очистьте й натріть овочі на грубій тертці; відіжміть зайву рідину, щоб маса тримала форму.`,t:[`peeling`,`coarse-grating`,`squeezing-out-moisture`],m:10,i:[[`potato`,700,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:8,i:[[`all-purpose-flour`,160,`g`],[`chicken-egg`,1,`pcs`],[`table-salt`,4,`g`]]},{en:`Cook dumplings in batches in gently boiling salted water for about 9 minutes, until they float and the filling is cooked through. Lift out with a slotted spoon.`,ua:`Варіть вироби порціями в ледь киплячій підсоленій воді приблизно 9 хвилин, доки вони спливуть і начинка приготується. Вийміть шумівкою.`,t:[`boiling`],m:9,i:[[`water`,1200,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 8 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 8 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:8,i:[[`bacon`,160,`g`],[`unsalted-butter`,35,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`bryndza`,230,`g`],[`sour-cream`,110,`g`]]}];var d={slug:i,id:n,country:`SK`,region:o,servings:4,minutes:37,title:l,text:g,steps:u};export{a as country,d as default,n as id,r as minutes,o as region,s as servings,i as slug,u as steps,g as text,l as title};